1141	\begin{lemma}[Direct sums give product distributions]\label{lem:cl-dist-prod}
1142		\lean{MIPStarRE.QPBT.clDistribution_directSum_eq_prod}
1143		\leanok
1144		\uses{def:cl-dist, lem:cl-func-prod}
1145		For each $i \in \{1, \dots, m\}$ let $L^{(i)}, R^{(i)} \colon V^{(i)} \to V^{(i)}$ be $\ell_i$-level conditionally linear functions, and let $L, R \colon V \to V$ be the direct sums $L = \bigoplus_i L^{(i)}$ and $R = \bigoplus_i R^{(i)}$, as defined in Lemma~\ref{lem:cl-func-prod}. Then the conditionally linear distribution $\mu_{L,R}$ is the product distribution $\prod_{i=1}^m \mu_{L^{(i)},\,R^{(i)}}$ over $V \times V$.
1146	\end{lemma}
1147	\begin{proof}
1148		\leanok
1149		\uses{lem:cl-supported-vanishing, lem:cl-supported-restriction, lem:cl-restriction-sum}
1150		A uniformly random $x \in V$ has independent components $x^{(i)}$, each uniformly distributed in $V^{(i)}$. Hence the pair $(L(x), R(x)) = \bigl( (L^{(i)}(x^{(i)}))_{i=1}^m,\, (R^{(i)}(x^{(i)}))_{i=1}^m \bigr)$ is distributed exactly as the product of the distributions $\mu_{L^{(i)},\,R^{(i)}}$ for $i = 1, 2, \dots, m$.
1151	\end{proof}
