1219	\label{sec:types}
1220	
1221	The question distribution of the Pauli basis test is \emph{typed}: each question is a pair consisting of a type, drawn together with the other player's type from the edges of a fixed \emph{type graph}, and a question content, drawn from a CL distribution determined by the pair of types.
1222	
1223	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
1224		\lean{MIPStarRE.QPBT.IsTypedCondLinearFamily}
1225		\leanok
1226		\uses{def:cl-func}
1227		Let $\mathcal T$ be a finite set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$.
1228	\end{definition}
1229	
1230	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
1231	% normalization 1/(2m-k) below is undefined. The source
1232	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
1233	\begin{definition}[Graph distribution]\label{def:graph-distribution}
1234		\lean{MIPStarRE.QPBT.graphDistribution}
1235		\leanok
1236		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
1237		\[
1238			\mu_G(u, v) =
1239			\begin{cases}
1240				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
1241				0 & \text{otherwise}\,.
1242			\end{cases}
1243		\]
1244		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
1245	\end{definition}
1246	
1247	\begin{lemma}[Total mass of the graph distribution]\label{lem:graph-distribution-mass}
1248		\lean{MIPStarRE.QPBT.graphDistribution_isProbability}
1249		\leanok
1250		\uses{def:graph-distribution}
1251		Let $G = (U, E)$ be an undirected graph with nonempty edge set $E$. Then the graph distribution $\mu_G$ of Definition~\ref{def:graph-distribution} has total mass one, that is, $\sum_{(u,v) \in U \times U} \mu_G(u,v) = 1$.
1252	\end{lemma}
1253	\begin{proof}
1254		\leanok
1255		\uses{def:graph-distribution}
1256		The distribution $\mu_G$ is uniform on the set of ordered pairs $(u,v) \in U \times U$ with $\{u,v\} \in E$, and that set is nonempty because $E$ is: an edge $\{u,v\} \in E$ yields the ordered pair $(u,v)$. A uniform distribution on a nonempty finite set has total mass one.
1257	\end{proof}
