1146	\section{Typed conditionally linear distributions}
1147	% Paper section label sec:types kept for cross-reference fidelity. Only the mathematical
1148	% typed material (typed CL functions and distributions, graph distributions) is stated
1149	% here; the typed sampler and verifier machinery of the source is outside the scope of
1150	% the mathematical development.
1151	\label{sec:types}
1152	
1153	The question distribution of the Pauli basis test is \emph{typed}: each question is a pair consisting of a type, drawn together with the other player's type from the edges of a fixed \emph{type graph}, and a question content, drawn from a CL distribution determined by the pair of types.
1154	
1155	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
1156		\lean{MIPStarRE.QPBT.IsTypedCondLinearFamily}
1157		\leanok
1158		\uses{def:cl-func}
1159		Let $\mathcal T$ be a finite set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$.
1160	\end{definition}
1161	
1162	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
1163	% normalization 1/(2m-k) below is undefined. The source
1164	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
1165	\begin{definition}[Graph distribution]\label{def:graph-distribution}
1166		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
1167		\[
1168			\mu_G(u, v) =
1169			\begin{cases}
1170				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
1171				0 & \text{otherwise}\,.
1172			\end{cases}
1173		\]
1174		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
1175	\end{definition}
1176	
1177	% The nonempty-edge hypothesis on G is inherited from def:graph-distribution, where it is
1178	% needed for the graph distribution mu_G to be defined; the source
1179	% (references/qpbt-paper/07_types.tex:84-93) leaves it implicit here as well.
1180	\begin{definition}[Typed conditionally linear distributions]\label{def:typed-cl-distributions}
1181		\lean{MIPStarRE.QPBT.typedCLDistribution, MIPStarRE.QPBT.ldQuestionDistribution_eq_typedCL, MIPStarRE.QPBT.pauliQuestionDistribution_eq_typedCL}
1182		\leanok
1183		\uses{def:typed-cl-functions, def:graph-distribution, def:cl-dist}
1184		Let $\mathcal T$ be a type set and let $L = \{L_u\}_{u \in \mathcal T}$ and $R = \{R_v\}_{v \in \mathcal T}$ be $\mathcal T$-typed families of conditionally linear functions on $V$. Let $G = (\mathcal T, E)$ be a graph with vertex set $\mathcal T$ and nonempty edge set $E$, so that the graph distribution $\mu_G$ of Definition~\ref{def:graph-distribution} is defined. The \emph{$(\mathcal T, G)$-typed conditionally linear distribution $\mu^G_{L,\,R}$ corresponding to $(L, R)$} is the distribution over pairs $\bigl( (u, x), (v, y) \bigr)$, where the type pair $(u,v)$ is drawn from the graph distribution $\mu_G$ and the content pair $(x,y)$ is drawn from $\mu_{L_u,\,R_v}$.
1185	\end{definition}

